<?php
namespace App\Http\Controllers;
use App\Models\{Employee,AttendanceRecord,AttendancePunch,WorkflowRequest,PayrollPeriod,Payslip,PayrollAdjustment,KioskDevice,ReportExport,SalaryHistory,ApprovedLeave,LeaveBalance};
use App\Services\{PayrollService,Policy,Audit,ScheduleService};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class PortalController extends Controller {
 public function index(Request $r){
  $admin=$r->user()->role==='admin';$page=$r->input('page',$admin?'dashboard':'attendance');$allowed=$admin?['dashboard','workforce','attendance','requests','payroll','payslips','reports','settings','audit','appraisals']:['attendance','requests','leave','payslips','profile'];abort_unless(in_array($page,$allowed,true),404);
  $v=$r->validate(['q'=>'nullable|string|max:100','from'=>'nullable|date_format:Y-m-d','to'=>'nullable|date_format:Y-m-d|after_or_equal:from','employee_id'=>'nullable|integer','period_id'=>'nullable|uuid','status'=>'nullable|in:pending,approved,rejected,pending_ems,cancelled','record_status'=>'nullable|in:completed,late,incomplete,partial,in_progress,early_out,corrected','work_status'=>'nullable|in:active,on_leave,absent,inactive,retired,terminated,resigned','card_status'=>'nullable|in:assigned,unassigned','pay_status'=>'nullable|in:draft,released','pay_attendance'=>'nullable|in:completed,late,early_out,incomplete,partial','request_type'=>'nullable|in:overtime,schedule_change,manual_attendance,deduction,loan,tax,leave']);
  $q=$v['q']??'';$from=$v['from']??now()->timezone('Asia/Manila')->startOfMonth()->toDateString();$to=$v['to']??now()->timezone('Asia/Manila')->endOfMonth()->toDateString();$eid=$admin?($v['employee_id']??null):$r->user()->employee_id;
  $employees=$admin?Employee::when($v['work_status']??null,fn($x,$status)=>$x->whereRaw('LOWER(status) = ?',[$status]))->when($v['card_status']??null,fn($x,$card)=>$card==='assigned'?$x->whereNotNull('rfid_uid')->where('rfid_uid','!=',''):$x->where(fn($y)=>$y->whereNull('rfid_uid')->orWhere('rfid_uid','')))->when($q,fn($x)=>$x->where(fn($y)=>$y->where('employee_no','like','%'.$q.'%')->orWhere('full_name','like','%'.$q.'%')->orWhere('department','like','%'.$q.'%')))->orderBy('employee_no')->get():collect([$r->user()->employee])->filter();
  $selected=$admin&&$eid?Employee::with('schedules','salaryHistory')->findOrFail($eid):$r->user()->employee;
  $attendanceQuery=AttendanceRecord::with('employee.schedules')->when($eid,fn($x)=>$x->where('employee_id',$eid))->whereBetween('work_date',[$from,$to])->when($q,fn($x)=>$x->whereHas('employee',fn($e)=>$e->where('full_name','like','%'.$q.'%')->orWhere('employee_no','like','%'.$q.'%')))->orderByDesc('work_date')->orderBy('employee_id');
  $decorate=function($row){$row->setAttribute('metrics',app(ScheduleService::class)->summary($row->employee,$row->work_date,$row));return $row;};
  if(!empty($v['record_status'])){$all=$attendanceQuery->get()->map($decorate)->filter(fn($row)=>$v['record_status']==='corrected'?$row->source==='Approved correction':$row->metrics['status_code']===$v['record_status'])->values();$pn=max(1,(int)$r->input('attendance_page',1));$attendance=new \Illuminate\Pagination\LengthAwarePaginator($all->forPage($pn,30)->values(),$all->count(),30,$pn,['path'=>$r->url(),'pageName'=>'attendance_page']);$attendance->withQueryString();}
  else $attendance=$attendanceQuery->paginate(30,['*'],'attendance_page')->withQueryString()->through($decorate);
  $requests=WorkflowRequest::with('employee')->when($page==='leave',fn($x)=>$x->where('type','leave'))->when($q,fn($x)=>$x->where(fn($y)=>$y->where('request_id','like','%'.$q.'%')->orWhere('type','like','%'.$q.'%')->orWhere('reason','like','%'.$q.'%')->orWhereHas('employee',fn($e)=>$e->where('full_name','like','%'.$q.'%')->orWhere('employee_no','like','%'.$q.'%'))))->when($eid,fn($x)=>$x->where('employee_id',$eid))->when($v['status']??null,fn($x,$status)=>$x->where('status',$status))->when($v['request_type']??null,fn($x,$kind)=>$x->where('type',$kind))->when($r->filled('from'),fn($x)=>$x->whereDate('work_date','>=',$from))->when($r->filled('to'),fn($x)=>$x->whereDate('work_date','<=',$to))->orderByDesc('created_at')->paginate(20,['*'],'requests_page')->withQueryString();
  $periods=PayrollPeriod::orderByDesc('starts_on')->get();$period=isset($v['period_id'])?PayrollPeriod::where('period_id',$v['period_id'])->firstOrFail():$periods->first();
  $payslips=Payslip::when($q,fn($x)=>$x->where(fn($y)=>$y->where('employee_no','like','%'.$q.'%')->orWhereIn('employee_no',Employee::where('full_name','like','%'.$q.'%')->select('employee_no'))->orWhereIn('period_id',PayrollPeriod::where('starts_on','like','%'.$q.'%')->orWhere('ends_on','like','%'.$q.'%')->select('period_id'))))->when($admin||$r->filled('period_id'),fn($x)=>$x->where('period_id',$period?->period_id))->when($v['pay_status']??null,fn($x,$status)=>$x->where('status',$status))->when(!$admin,fn($x)=>$x->where('employee_no',$r->user()->employee?->employee_no)->where('status','released'))->orderBy('employee_no')->get()->when($v['pay_attendance']??null,fn($rows,$state)=>$rows->filter(fn($slip)=>app(PayrollService::class)->attendanceStatus($slip->calculation??[])===$state));
  $policy=Policy::get();$devices=$admin?KioskDevice::orderByDesc('id')->get():collect();$syncRuns=$admin?DB::table('ems_sync_runs')->orderByDesc('id')->limit(15)->get():collect();
  $reports=$admin?ReportExport::orderByDesc('id')->limit(30)->get():collect();$audit=$admin?DB::table('audit_events')->leftJoin('users','users.id','=','audit_events.user_id')->select('audit_events.*','users.name as actor')->orderByDesc('audit_events.id')->limit(100)->get():collect();
  $salaryChanges=$admin?SalaryHistory::with('employee')->when($q,fn($x)=>$x->whereHas('employee',fn($y)=>$y->where('employee_no','like','%'.$q.'%')->orWhere('full_name','like','%'.$q.'%')))->when($r->filled('from'),fn($x)=>$x->whereDate('effective_on','>=',$from))->when($r->filled('to'),fn($x)=>$x->whereDate('effective_on','<=',$to))->orderByDesc('effective_on')->limit(200)->get():collect();
  $leaveBalances=LeaveBalance::with('employee')->when(!$admin,fn($x)=>$x->where('employee_id',$r->user()->employee_id))->when($admin&&$q,fn($x)=>$x->whereHas('employee',fn($y)=>$y->where('employee_no','like','%'.$q.'%')->orWhere('full_name','like','%'.$q.'%')))->orderBy('leave_type')->limit(200)->get();
  $emsLeaves=$admin?ApprovedLeave::with('employee')->when($q,fn($x)=>$x->whereHas('employee',fn($y)=>$y->where('employee_no','like','%'.$q.'%')->orWhere('full_name','like','%'.$q.'%')))->when($r->filled('from'),fn($x)=>$x->whereDate('ends_on','>=',$from))->when($r->filled('to'),fn($x)=>$x->whereDate('starts_on','<=',$to))->orderByDesc('starts_on')->limit(200)->get():collect();
  return view('app.portal',compact('salaryChanges','emsLeaves','leaveBalances','admin','page','employees','selected','attendance','requests','periods','period','payslips','policy','devices','syncRuns','reports','audit','q','from','to','eid'));
 }
 public function compute(Request $r){$v=$r->validate(['period_start'=>'required|date_format:Y-m-d']);$p=app(PayrollService::class)->period($v['period_start']);app(PayrollService::class)->compute($p,$r->user()->id);return redirect('/?page=payroll&period_id='.$p->period_id)->with('success','Payroll computed from verified database records. Review the breakdown before release.');}
 public function release(Request $r,Payslip $payslip){$v=$r->validate(['action'=>'required|in:release,withdraw']);app(PayrollService::class)->release($payslip,$v['action']==='release',$r->user()->id);return back()->with('success','Payslip '.$v['action'].' saved for this employee and cut-off only.');}
 public function releaseAll(Request $r,PayrollPeriod $period){$count=app(PayrollService::class)->releaseAll($period,$r->user()->id);return back()->with('success','Released '.$count.' payslips in this cut-off.');}
 public function payslip(Request $r,string $id){$p=Payslip::where('payslip_id',$id)->firstOrFail();abort_unless($r->user()->role==='admin'||($p->status==='released'&&$r->user()->employee?->employee_no===$p->employee_no),403);$period=PayrollPeriod::where('period_id',$p->period_id)->firstOrFail();$e=Employee::where('employee_no',$p->employee_no)->firstOrFail();Audit::record('payslip_viewed','payslips',$p->payslip_id);$html=view('app.payslip',['slip'=>$p,'period'=>$period,'employee'=>$e])->render();if($r->boolean('pdf'))return $this->pdf($html,'payslip-'.$p->payslip_id.'.pdf');return response($html)->header('Cache-Control','private, no-store');}
 private function pdf(string $html,string $filename){$pdf=new \Dompdf\Dompdf(['isRemoteEnabled'=>false,'defaultFont'=>'DejaVu Sans']);$pdf->loadHtml($html);$pdf->setPaper('A4',str_contains($filename,'report-')?'landscape':'portrait');$pdf->render();return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="'.$filename.'"','Cache-Control'=>'private, no-store']);}
 public function createReport(Request $r){
  $v=$r->validate(['type'=>'required|in:payroll,attendance,requests','from'=>'required|date_format:Y-m-d','to'=>'required|date_format:Y-m-d|after_or_equal:from','q'=>'nullable|string|max:100','status'=>'nullable|in:pending,pending_ems,approved,rejected,cancelled','request_type'=>'nullable|in:overtime,schedule_change,manual_attendance,deduction,loan,tax,leave','pay_status'=>'nullable|in:draft,released','pay_attendance'=>'nullable|in:completed,late,early_out,incomplete,partial','record_status'=>'nullable|in:completed,late,incomplete,partial,in_progress,early_out,corrected']);$rows=[];$search=$v['q']??'';$employeeFilter=fn($x)=>$x->when($search,fn($q)=>$q->whereHas('employee',fn($e)=>$e->where('full_name','like','%'.$search.'%')->orWhere('employee_no','like','%'.$search.'%')));
  if($v['type']==='payroll'){
   $ids=PayrollPeriod::where('starts_on','>=',$v['from'])->where('ends_on','<=',$v['to'])->pluck('period_id');
   foreach(Payslip::whereIn('period_id',$ids)->when($v['pay_status']??null,fn($q,$status)=>$q->where('status',$status))->when($search,fn($q)=>$q->where(fn($x)=>$x->where('employee_no','like','%'.$search.'%')->orWhereIn('employee_no',Employee::where('full_name','like','%'.$search.'%')->select('employee_no'))))->orderBy('employee_no')->get()->when($v['pay_attendance']??null,fn($rows,$state)=>$rows->filter(fn($slip)=>app(PayrollService::class)->attendanceStatus($slip->calculation??[])===$state)) as $p)$rows[]=['employee_no'=>$p->employee_no,'employee_name'=>$p->calculation['employee_name']??Employee::where('employee_no',$p->employee_no)->value('full_name'),'starts_on'=>$p->calculation['starts_on']??'','ends_on'=>$p->calculation['ends_on']??'','gross_pay'=>$p->gross_pay,'sss'=>$p->calculation['sss']??'0.00','gsis'=>$p->calculation['gsis']??'0.00','philhealth'=>$p->calculation['philhealth']??'0.00','pagibig'=>$p->calculation['pagibig']??'0.00','tax'=>$p->calculation['tax']??'0.00','loan'=>$p->calculation['loan']??'0.00','deductions'=>$p->deductions,'net_pay'=>$p->net_pay,'status'=>$p->status];
  }elseif($v['type']==='attendance')foreach($employeeFilter(AttendanceRecord::with('employee.schedules')->whereBetween('work_date',[$v['from'],$v['to']]))->orderBy('work_date')->get()->filter(function($a)use($v){if(empty($v['record_status']))return true;$m=app(ScheduleService::class)->summary($a->employee,$a->work_date,$a);return $v['record_status']==='corrected'?$a->source==='Approved correction':$m['status_code']===$v['record_status'];}) as $a)$rows[]=['employee_no'=>$a->employee->employee_no,'name'=>$a->employee->full_name,'date'=>$a->work_date,'am_in'=>$a->am_in?->timezone('Asia/Manila')->format('H:i')??'','am_out'=>$a->am_out?->timezone('Asia/Manila')->format('H:i')??'','pm_in'=>$a->pm_in?->timezone('Asia/Manila')->format('H:i')??'','pm_out'=>$a->pm_out?->timezone('Asia/Manila')->format('H:i')??'','late_minutes'=>app(ScheduleService::class)->summary($a->employee,$a->work_date,$a)['late_minutes'],'actual_minutes'=>app(ScheduleService::class)->summary($a->employee,$a->work_date,$a)['worked_minutes'],'uncovered_minutes'=>app(ScheduleService::class)->summary($a->employee,$a->work_date,$a)['uncovered_minutes'],'source'=>$a->source];
  else foreach(WorkflowRequest::with('employee')->whereBetween('work_date',[$v['from'],$v['to']])->when($v['status']??null,fn($q,$state)=>$q->where('status',$state))->when($v['request_type']??null,fn($q,$kind)=>$q->where('type',$kind))->when($search,fn($q)=>$q->where(fn($x)=>$x->where('request_id','like','%'.$search.'%')->orWhere('reason','like','%'.$search.'%')->orWhereHas('employee',fn($e)=>$e->where('full_name','like','%'.$search.'%')->orWhere('employee_no','like','%'.$search.'%'))))->orderBy('created_at')->get() as $q)$rows[]=['request_id'=>$q->request_id,'employee_no'=>$q->employee->employee_no,'type'=>$q->type,'date'=>$q->work_date,'status'=>$q->status,'reviewed_at'=>$q->reviewed_at?->utc()->toIso8601ZuluString()??''];
  $uuid=(string)Str::uuid();$report=ReportExport::create(['report_id'=>$uuid,'control_number'=>'PMS-'.strtoupper($uuid),'type'=>$v['type'],'filters'=>$v,'snapshot'=>['rows'=>$rows,'signatory'=>Policy::get()['signatory']??'','signatory_title'=>Policy::get()['signatory_title']??'','prepared_by'=>Policy::get()['report_preparer']??$r->user()->name,'reviewed_by'=>Policy::get()['report_reviewer']??''],'user_id'=>$r->user()->id]);Audit::record('report_generated','report_exports',$uuid,['type'=>$v['type']]);return redirect('/reports/'.$report->report_id);
 }
 public function report(Request $r,string $id){$report=ReportExport::where('report_id',$id)->firstOrFail();Audit::record('report_viewed','report_exports',$id);$rows=$report->snapshot['rows'];
  if($r->boolean('csv')){Audit::record('report_exported','report_exports',$id);return response()->streamDownload(function()use($rows){$h=fopen('php://output','w');if($rows)fputcsv($h,array_keys($rows[0]),',','"','');foreach($rows as $row)fputcsv($h,array_map(fn($s)=>preg_match('/^[=+@\-\t\r]/',(string)$s)?"'".$s:$s,$row),',','"','');fclose($h);},'report-'.$report->report_id.'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
  $html=view('app.report',compact('report','rows'))->render();return $r->boolean('pdf')?$this->pdf($html,'report-'.$report->report_id.'.pdf'):response($html)->header('Cache-Control','private, no-store');
 }
}
